<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$pdo=db();
$counts=$pdo->prepare("SELECT COUNT(*) pledges, SUM(status='received') received, SUM(status IN('pending','approved','scheduled')) active FROM donation_pledges WHERE donor_id=?");$counts->execute([$user['id']]);$counts=$counts->fetch()?:['pledges'=>0,'received'=>0,'active'=>0];
$itemCount=$pdo->prepare("SELECT COALESCE(SUM(di.quantity),0) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id WHERE dp.donor_id=? AND dp.status='received'");$itemCount->execute([$user['id']]);$items=(int)$itemCount->fetchColumn();
$pledgeStmt=$pdo->prepare("SELECT dp.*,cr.title,c.organization_name,COALESCE(SUM(di.quantity),0) quantity,a.appointment_date,a.time_slot FROM donation_pledges dp JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id LEFT JOIN donation_items di ON di.pledge_id=dp.id LEFT JOIN appointments a ON a.pledge_id=dp.id AND a.status='booked' WHERE dp.donor_id=? GROUP BY dp.id ORDER BY FIELD(dp.status,'scheduled','approved','pending','received','cancelled'),dp.created_at DESC LIMIT 7");$pledgeStmt->execute([$user['id']]);$pledges=$pledgeStmt->fetchAll();
$appointments=$pdo->prepare("SELECT a.*,cr.title,c.organization_name,cr.collection_location FROM appointments a JOIN donation_pledges dp ON dp.id=a.pledge_id JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id WHERE dp.donor_id=? AND a.status='booked' AND a.appointment_date>=CURDATE() ORDER BY a.appointment_date,a.time_slot LIMIT 3");$appointments->execute([$user['id']]);$appointments=$appointments->fetchAll();
$pageTitle='Your giving dashboard';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">Your giving has a ripple</span><h1>Hi, <?=e(explode(' ',$user['name'])[0])?>.</h1><p>Thanks for making useful clothes count twice.</p></div><a class="button" href="<?=e(url('donor/browse.php'))?>">Find a new need →</a></div>
<div class="stat-cards"><article class="stat-card"><span class="label">Items received</span><strong><?=$items?></strong><small>pieces now doing good</small></article><article class="stat-card"><span class="label">Active pledges</span><strong><?= (int)$counts['active']?></strong><small>waiting for their next step</small></article><article class="stat-card"><span class="label">Completed drops</span><strong><?= (int)$counts['received']?></strong><small>charities confirmed</small></article><article class="stat-card"><span class="label">All pledges</span><strong><?= (int)$counts['pledges']?></strong><small>small promises made</small></article></div>
<div class="layout-two"><div class="panel"><div class="panel-heading"><h2>Your pledges</h2><a class="text-link" href="<?=e(url('donor/pledges.php'))?>">View all →</a></div><?php if(!$pledges):?><div class="empty"><span class="empty-icon">♥</span>Your giving story starts with one item. <a class="text-link" href="<?=e(url('donor/browse.php'))?>">Explore needs</a></div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Items</th><th>Status</th><th>Next step</th></tr></thead><tbody><?php foreach($pledges as $p):?><tr><td><strong><?=e($p['title'])?></strong><br><span class="muted"><?=e($p['organization_name'])?></span></td><td><?= (int)$p['quantity']?></td><td><span class="status <?=e(status_class($p['status']))?>"><?=e($p['status'])?></span></td><td><?php if($p['status']==='approved'):?><a class="text-link" href="<?=e(url('donor/appointment.php?pledge='.$p['id']))?>">Book drop-off</a><?php elseif($p['appointment_date']):?><?=format_date($p['appointment_date'],'D, d M')?><?php else:?><span class="muted">Charity review</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><aside class="panel"><div class="panel-heading"><h2>Upcoming drop-offs</h2></div><?php if(!$appointments):?><div class="empty"><span class="empty-icon">◷</span>No drop-offs booked just yet.</div><?php else:foreach($appointments as $a):?><div class="appointment-card"><strong><?=e($a['title'])?></strong><p>📅 <?=format_date($a['appointment_date'],'D, d M')?> at <?=e(substr($a['time_slot'],0,5))?><br>📍 <?=e($a['collection_location'])?></p></div><?php endforeach;endif;?></aside></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
